  feedback_summary_student = 'Кампус ДВФУ на острове Русском считается одним из самых впечатляющих в России — благоустроенная территория у океана, сильный преподавательский состав, насыщенная внеучебная жизнь и спортивная инфраструктура. Главная и постоянно повторяющаяся претензия студентов — общежитие гарантировано только на первом курсе, дальше нужно самим снимать дорогое жильё во Владивостоке, а расписание, особенно на старших курсах, называют неудобным.',
  feedback_positive_highlights = '{"впечатляющий кампус на острове Русском","сильный преподавательский состав"}',
  feedback_negative_highlights = '{"общежитие только на 1 курс","дорогое съёмное жильё после 1 курса"}',
  feedback_based_on_count = 16, feedback_generated_at = now(), updated_at = now()
where name = 'Дальневосточный федеральный университет' and city = 'Владивосток';

