update public.institutions set
  feedback_summary_student = 'Морской университет им. Невельского хвалят за сильную дисциплину, крепкий преподавательский состав и востребованность выпускников морских специальностей — некоторые не жалеют о выборе даже спустя годы после выпуска. Критикуют плохие бытовые условия в общежитиях (тараканы, клопы, старая техника), слабое питание и, по отдельным отзывам, финансовые проблемы вуза и элементы коррупции в командном составе.',
